window.LAWS = {"note": "Hand-verified against aph.gov.au bill pages. Statuses: scheduled (introduced, awaiting debate), debated (before Parliament), passed, failed (defeated, withdrawn or lapsed), repealed. Controversy entries report who objected and what they argued, with sources; they are not the site's own judgement.", "categories": ["Free speech", "Privacy & anonymity", "Civil liberties & detention", "Due process & sentencing", "Democratic process", "Cost & economic impact", "Environment", "Indigenous rights", "Immigration & borders", "Workers & business", "Religious freedom", "Other"], "laws": [{"id": "universities-accord-opening-the-doors-of-opportunity-bill-2026", "title": "Universities Accord (Opening the Doors of Opportunity) Bill 2026", "status": "debated", "status_date": "2026-09-17", "status_note": "Passed the House; before the Senate, second reading debated 15-17 Sep 2026", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7501", "legislation_url": null, "summary": "Amends the Higher Education Support Act 2003 to move university funding to a 'managed growth' system based on a total number of equivalent full-time student places, and provides needs-based funding grants for students from low socioeconomic backgrounds, First Nations students and regional-campus students. It also gives the Australian Tertiary Education Commission a framework to allocate international student places.", "controversy": {"category": "Cost & economic impact", "summary": "The Group of Eight told the Senate inquiry (12 Aug 2026) the bill risks 'replacing one barrier with another' and gives the Minister 'unchecked power to shape the character, purpose and behaviour' of autonomous universities. Universities Australia (24 Aug 2026) said the bill lacks a legislative guarantee that total system funding will cover existing student load and that a minister 'could still impose unreasonable conditions directly on the funding of an individual university'. The government says the bill implements the Universities Accord's recommendation for managed growth and needs-based funding.", "raised_by": ["Group of Eight", "Universities Australia"], "sources": [{"title": "Go8 submission to Senate inquiry into the Universities Accord (Opening the Doors of Opportunity) Bill 2026", "url": "https://go8.edu.au/go8-submission-to-senate-inquiry-into-the-universities-accord-opening-the-doors-of-opportunity-bill-2026"}, {"title": "Universities Australia opening statement to the inquiry", "url": "https://universitiesaustralia.edu.au/media-item/opening-statement-inquiry-into-the-universities-accord-opening-the-doors-of-opportunity-bill-2026/"}]}, "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "anti-money-laundering-and-counter-terrorism-financing-amendment-bill-2026", "title": "Anti-Money Laundering and Counter-Terrorism Financing Amendment Bill 2026", "status": "debated", "status_date": "2026-09-16", "status_note": "Third reading agreed in the House 16 Sep 2026 with 25 government amendments; awaiting Senate consideration", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7448", "legislation_url": null, "summary": "Amends the Anti-Money Laundering and Counter-Terrorism Financing Act 2006 to let the AUSTRAC Chief Executive Officer restrict or prohibit reporting entities from using high-risk mechanisms to provide designated services. It also updates the definition of financing of terrorism to reference new offences for financing a state sponsor of terrorism and makes technical amendments. The bill was reviewed by the Parliamentary Joint Committee on Intelligence and Security.", "controversy": null, "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "online-safety-amendment-strengthening-enforcement-for-the-social-media-minimum-age-act-2026", "title": "Online Safety Amendment (Strengthening Enforcement for the Social Media Minimum Age) Bill 2026", "status": "passed", "status_date": "2026-09-11", "status_note": "Passed both Houses 10 Sep 2026 with 2 government amendments; assented 11 Sep 2026 (Act No. 83 of 2026)", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7512", "legislation_url": "https://www.legislation.gov.au/C2026A00083/latest/text", "summary": "Amends the Online Safety Act 2021 to expand the eSafety Commissioner's information-gathering powers in relation to the social media minimum age framework and to increase civil penalties for non-compliance. It builds on the 2024 Act that set a minimum age of 16 for holding accounts on age-restricted social media platforms.", "controversy": null, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "automated-decision-making-safeguards-and-transparency-bill-2026", "title": "Automated Decision-Making (Safeguards and Transparency) Bill 2026", "status": "scheduled", "status_date": "2026-09-07", "status_note": "Private member's bill (Kate Chaney MP) introduced 7 Sep 2026; second reading moved; not yet debated", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7536", "legislation_url": null, "summary": "A private member's bill introduced in the House of Representatives on 7 September 2026 concerning safeguards and transparency for automated decision-making by government. No summary had been published on the bill's aph.gov.au page at the time of verification.", "controversy": null, "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "news-journalism-payments-act-2026", "title": "News Journalism Payments Bill 2026", "status": "passed", "status_date": "2026-08-26", "status_note": "Passed both Houses 20 Aug 2026; assented 26 Aug 2026 (Act No. 75 of 2026); part of a package with the News Media Bargaining Charge Bill 2026", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7528", "legislation_url": "https://www.legislation.gov.au/C2026A00075/latest/text", "summary": "Part of the government's 'news bargaining incentive' package. According to ABC reporting on the scheme, large digital platforms above a local revenue threshold face a charge on Australian revenue unless they strike commercial deals to pay news outlets, with the proceeds distributed to newsrooms. No summary had been published on the bill's aph.gov.au page at the time of verification.", "controversy": {"category": "Cost & economic impact", "summary": "Meta said the proposal was 'nothing more than a digital services tax' and a 'government-mandated transfer of wealth' with 'no connection to the value exchanged'; Google argued it ignored existing commercial agreements and 'arbitrarily' excluded other platforms (ABC, 28 Apr 2026). Communications Minister Anika Wells said it is 'only fair that large digital platforms contribute to the hard work of journalism that enriches their feeds'.", "raised_by": ["Meta", "Google"], "sources": [{"title": "Labor defends news payment plan as Meta, Google reject tax (ABC News)", "url": "https://www.abc.net.au/news/2026-04-28/big-tech-hits-back-at-labors-media-bargaining-plan/106617532"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "interactive-gambling-amendment-gambling-reform-act-2026", "title": "Interactive Gambling Amendment (Gambling Reform) Bill 2026", "status": "passed", "status_date": "2026-08-26", "status_note": "Passed the House 18 Aug 2026 with 26 government and 45 opposition amendments; passed Senate 19 Aug 2026; assented 26 Aug 2026 (Act No. 72 of 2026)", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7520", "legislation_url": "https://www.legislation.gov.au/C2026A00072/latest/text", "summary": "Amends the Interactive Gambling Act 2001 to establish new restrictions on wagering advertising, including a ban on wagering ads during live sports coverage and requirements for online services to stop restricted users receiving ads. It expands the BetStop national self-exclusion register, prohibits online keno and foreign matched lotteries, and imposes obligations on financial institutions and online services to block payments and access to designated interactive gambling services.", "controversy": {"category": "Other", "summary": "Grattan Institute's Kate Griffiths (The Conversation, 18 Aug 2026) argued the bill falls short of the 2023 Murphy inquiry's recommendation to phase out 'all gambling advertising on all media' within three years, retaining a daytime cap on TV ads and permitting inducements. The Alliance for Gambling Reform called for closing 'streaming and live sport loopholes' and banning inducements. The Coalition, Greens and crossbench pressed for stronger measures and the government agreed to amendments adding inducement restrictions; the government describes the Act as the most significant gambling advertising reform to date.", "raised_by": ["Grattan Institute", "Alliance for Gambling Reform", "Federal Opposition", "Australian Greens"], "sources": [{"title": "Long-awaited gambling reform bill is an improvement, but does not go nearly far enough (The Conversation)", "url": "https://theconversation.com/long-awaited-gambling-reform-bill-is-an-improvement-but-does-not-go-nearly-far-enough-to-reduce-harm-289382"}, {"title": "Alliance for Gambling Reform - Submission on the Gambling Reform Bill 2026", "url": "https://www.agr.org.au/submission-gamblingreformbill2026"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31", "public_reaction": {"summary": "Australia Institute/YouGov polling (12–19 Mar 2026, n=1,502) found 77% of Australians support a ban on gambling advertising, with majorities among voters of every party (Labor 81%, Coalition 78%, Greens 88%, One Nation 66%); a follow-up YouGov poll in June 2026 (n=2,230) found 79% support a total ban across TV, radio and online. An Alliance for Gambling Reform petition demanding a full ad ban had 35,243 signatures by July 2024. The 2023 House inquiry received 161 submissions and held 13 hearings; the 2026 Senate inquiry into this bill received 97 submissions and held two hearings.", "sources": [{"title": "Polling: banning gambling advertisements (The Australia Institute / YouGov, March 2026)", "url": "https://australiainstitute.org.au/report/polling-banning-gambling-advertising/", "date": "2026-05-11"}, {"title": "35,000 sign petition to end gambling ads (Alliance for Gambling Reform)", "url": "https://newshub.medianet.com.au/2024/07/35000-sign-petition-to-end-gambling-ads-reflects-white-hot-community-anger-at-proliferation-of-gambling-ads/56941/", "date": "2024-07-11"}, {"title": "Senate committee report on the Gambling Reform Bill 2026 (97 submissions, 2 hearings)", "url": "https://www.aph.gov.au/Parliamentary_Business/Committees/Senate/Environment_and_Communications/GamblingReform48P/Report", "date": "2026-08-17"}]}}, {"id": "asio-amendment-no-2-act-2026", "title": "Australian Security Intelligence Organisation Amendment Bill (No. 2) 2025", "status": "passed", "status_date": "2026-08-26", "status_note": "Introduced 23 Jul 2025; passed House 12 Feb 2026; passed Senate 20 Aug 2026 with 3 government amendments; assented 26 Aug 2026 (Act No. 81 of 2026, cited on legislation.gov.au as the ASIO Amendment Act (No. 2) 2026). A separate ASIO Amendment Act (No. 1) 2025 (Act No. 41 of 2025) had extended the questioning framework by 18 months.", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7339", "legislation_url": "https://www.legislation.gov.au/C2026A00081/latest/text", "summary": "As introduced, the bill amends the ASIO Act 1979 to make ASIO's compulsory questioning warrant framework permanent, expand the scope of adult questioning warrants to ASIO's full security mandate, amend the eligibility of prescribed authorities, add reporting requirements to the Attorney-General, and require post-charge questioning to occur only before a retired judge. It also provides for a further review by the Parliamentary Joint Committee on Intelligence and Security.", "controversy": {"category": "Civil liberties & detention", "summary": "The Law Council of Australia (17 Nov 2025) opposed removing the sunset clause, with President Juliana Warner saying 'just because they have been in place for an extended period does not mean we should lose sight of the fact that they are extraordinary powers', and criticised the retention of questioning powers over children aged 14 and over and the expansion to ASIO's full security mandate. In a 28 May 2026 update the Law Council welcomed a government amendment to retain the sunset clause and further amendments on children under 14 and legal representation; the government's stated rationale was to keep the powers 'fit for purpose' for the contemporary threat environment.", "raised_by": ["Law Council of Australia"], "sources": [{"title": "Extraordinary ASIO powers should not become permanent without further justification (Law Council)", "url": "https://lawcouncil.au/media/media-releases/extraordinary-asio-powers-should-not-become-permanent-without-further-justification"}, {"title": "ASIO Amendment Bill (No. 2) 2025 - Advocacy Update (Law Council)", "url": "https://lawcouncil.au/media/news/asio-amendment-bill-no--2-2025-advocacy-update"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31", "public_reaction": {"summary": "No opinion polling, e-petition, public petition or protest specifically on ASIO's compulsory questioning powers was found. The intelligence committee's review of the bill received only six submissions, two of them from individuals; the rest came from Home Affairs, ASIO, the Law Council and a joint submission from civil-liberties councils.", "sources": [{"title": "Submissions to the PJCIS review of the ASIO Amendment Bill (No. 2) 2025 (6 items)", "url": "https://www.aph.gov.au/Parliamentary_Business/Committees/Joint/Intelligence_and_Security/ASIOBill22025/Submissions", "date": "2025-10"}, {"title": "Why some of ASIO's most controversial powers have been expanded (ABC News)", "url": "https://www.abc.net.au/news/2026-08-27/why-some-asio-most-controversial-powers-have-been-expanded/107084866", "date": "2026-08-27"}]}}, {"id": "counter-terrorism-legislation-amendment-bill-2026", "title": "Counter-Terrorism Legislation Amendment Bill 2026", "status": "debated", "status_date": "2026-08-20", "status_note": "Passed the House 20 Aug 2026; before the Senate (second reading moved 20 Aug 2026); referred to the PJCIS for review", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7527", "legislation_url": null, "summary": "According to the Parliamentary Library preliminary digest, the bill extends the sunset dates for key counter-terrorism police powers and the control order and post-sentence order frameworks for a further three years to 7 December 2029. It repositions control orders as the primary mechanism for imposing conditions on serious terrorist offenders after release, enables warrants and information sharing when a control order is being considered, and amends the terrorist organisation listing framework. The Attorney-General said the bill responds to the Bondi attack and an 'evolving' threat environment.", "controversy": null, "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "ndis-amendment-securing-the-ndis-for-future-generations-act-2026", "title": "National Disability Insurance Scheme Amendment (Securing the NDIS for Future Generations) Bill 2026", "status": "passed", "status_date": "2026-08-20", "status_note": "Passed both Houses 19 Aug 2026; assented 20 Aug 2026 (Act No. 66 of 2026)", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7487", "legislation_url": "https://www.legislation.gov.au/C2026A00066/latest/text", "summary": "Amends the NDIS Act 2013 to define 'functional capacity', limit unscheduled plan reassessments, require supports to relate directly to a participant's eligible impairments, allow the Minister to reduce funding for specified groups of supports, introduce plan end dates and renewal processes, and refine the 'reasonable and necessary' test. It also requires consideration of eligibility for other service systems and expands the NDIA's fraud and compliance powers.", "controversy": {"category": "Other", "summary": "Advocacy for Inclusion (5 Jun 2026) said government modelling showed 'hundreds of thousands of people with disability will be removed from or denied access to the scheme by 2031' and drew parallels with Robodebt over automated decision-making and weakened review rights. The Law Council of Australia (10 Jun 2026) said the consultation timeframe was 'unacceptably short' and that the bill's financial approach 'risks undermining original goals of the NDIS such as its participant-centred approach'. The government presents the changes as necessary to secure the scheme's long-term sustainability.", "raised_by": ["Advocacy for Inclusion", "Law Council of Australia"], "sources": [{"title": "Advocacy for Inclusion - NDIS Amendment (Securing the NDIS for Future Generations) Bill 2026", "url": "https://www.advocacyforinclusion.org/ndis-amendment-securing-the-ndis-for-future-generations-bill-2026/"}, {"title": "Law Council of Australia - NDIS Amendment Bill 2026", "url": "https://lawcouncil.au/media/news/national-disability-insurance-scheme-amendment-securing-the-ndis-for-future-generations-bill-2026"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "treasury-laws-amendment-tax-reform-no-1-act-2026", "title": "Treasury Laws Amendment (Tax Reform No. 1) Bill 2026", "status": "passed", "status_date": "2026-06-26", "status_note": "Introduced 28 May 2026 after the 12 May 2026 Budget; passed both Houses 25 Jun 2026 with 30 government and 3 Greens amendments; assented 26 Jun 2026 (Act No. 49 of 2026). Companion Income Tax Rates Amendment (Tax Reform No. 1) Act 2026 is Act No. 50 of 2026.", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7493", "legislation_url": "https://www.legislation.gov.au/C2026A00049/latest/text", "summary": "Replaces the 50 per cent capital gains tax discount for individuals, trusts and partnerships with cost base indexation and a 30 per cent minimum tax rate on gains accruing from 1 July 2027. It limits negative gearing for residential property investments to new builds from 1 July 2027, introduces a non-refundable tax offset for labour income from 2027-28, and provides a $1,000 standard deduction for work-related expenses from 2026-27.", "controversy": {"category": "Cost & economic impact", "summary": "ABC reported (12 May 2026) that the changes broke a 2026 election commitment not to alter negative gearing or CGT, quoting the Prime Minister's earlier 'For the 50th time' assurance. Shadow Treasurer Tim Wilson said the changes would 'lead to 35,000 fewer homes and higher rents' and the Coalition has pledged to repeal them. Treasurer Jim Chalmers argued the tax system had 'got out of whack' and that investor dominance was locking young people out of housing.", "raised_by": ["Federal Opposition (Tim Wilson)"], "sources": [{"title": "Government breaks promise with restrictions to negative gearing and CGT discount (ABC News)", "url": "https://www.abc.net.au/news/2026-05-12/budget-2026-government-breaks-promise-negative-gearing-cgt/106669860"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "commonwealth-electoral-amendment-voter-protections-in-political-advertising-bill-2026", "title": "Commonwealth Electoral Amendment (Voter Protections in Political Advertising) Bill 2026", "status": "scheduled", "status_date": "2026-06-22", "status_note": "Private member's bill (Zali Steggall MP) introduced 22 Jun 2026; second reading moved; not yet debated", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7496", "legislation_url": null, "summary": "Amends the Commonwealth Electoral Act 1918 to prohibit misleading or deceptive electoral or referendum matter, and the Referendum (Machinery Provisions) Act 1984 to impose additional transparency and standards requirements for political advertising. It is the latest of several 'truth in political advertising' private members' bills; the government's own Electoral Communications Bill 2024 lapsed at the 2025 dissolution.", "controversy": null, "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "secrecy-provisions-amendment-repealing-offences-bill-2026", "title": "Secrecy Provisions Amendment (Repealing Offences) Bill 2026", "status": "debated", "status_date": "2026-06-22", "status_note": "Passed the House 14 May 2026; before the Senate (second reading moved 22 Jun 2026); Senate committee reported 19 Jun 2026", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7467", "legislation_url": null, "summary": "Replaces the existing Criminal Code offence for unauthorised disclosure of information by Commonwealth officers with a new offence for improper use or communication of information done with intent to obtain a benefit or cause detriment. It requires the Attorney-General's consent to prosecute journalists for secrecy offences, and removes or decriminalises secrecy offences and non-disclosure duties across more than 300 provisions in 17 Acts and 5 regulations.", "controversy": {"category": "Free speech", "summary": "The Law Council of Australia (submission 22 May 2026, update 7 Jul 2026) supported the reform overall but said the new general secrecy offence could 'bring persons who provide unpaid services to the Commonwealth within a secrecy offence framework' designed for public servants, and sought a narrower definition of 'services', materiality thresholds and broader public-interest exceptions beyond journalists. The government's rationale is to reduce Commonwealth secrecy provisions by more than a third while retaining a targeted offence.", "raised_by": ["Law Council of Australia"], "sources": [{"title": "Law Council of Australia - Secrecy Provisions Amendment (Repealing Offences) Bill 2026", "url": "https://lawcouncil.au/media/news/secrecy-provisions-amendment-repealing-offences-bill-2026"}]}, "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "interactive-gambling-amendment-stop-the-gambling-ads-bill-2026", "title": "Interactive Gambling Amendment (Stop the Gambling Ads) Bill 2026", "status": "scheduled", "status_date": "2026-03-30", "status_note": "Private member's bill (Kate Chaney MP) introduced 30 Mar 2026; second reading moved; not yet debated", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7459", "legislation_url": null, "summary": "Amends the Interactive Gambling Act 2001 to prohibit advertising of licensed interactive wagering services in Australia, subject to limited exceptions and phased implementation. It is a private member's bill and sits alongside the government's narrower Gambling Reform Act 2026.", "controversy": null, "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "australian-criminal-intelligence-commission-bill-2026", "title": "Australian Criminal Intelligence Commission Bill 2026", "status": "scheduled", "status_date": "2026-03-25", "status_note": "Government bill introduced in the House 25 Mar 2026; second reading moved the same day; no further debate recorded as at 18 Sep 2026", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7454", "legislation_url": null, "summary": "Continues the Australian Criminal Intelligence Commission as the national criminal intelligence agency with realigned functions and powers to obtain, analyse and communicate intelligence on serious and organised crime. It also provides for nationally coordinated criminal history checks and criminal intelligence assessments. A companion bill imposes a charge for criminal history check applications.", "controversy": null, "verified_on": "2026-09-18", "recheck_by": "2026-10-16"}, {"id": "treasury-laws-amendment-building-a-stronger-and-fairer-super-system-act-2026", "title": "Treasury Laws Amendment (Building a Stronger and Fairer Super System) Bill 2026", "status": "passed", "status_date": "2026-03-13", "status_note": "Passed both Houses 10 Mar 2026; assented 13 Mar 2026 (Act No. 8 of 2026). Replaced the lapsed Better Targeted Superannuation Concessions Bill 2023.", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7437", "legislation_url": "https://www.legislation.gov.au/C2026A00008/latest/text", "summary": "Together with an imposition bill, reduces tax concessions for individuals with total superannuation balances above $3 million (the 'Division 296' measure) and makes consequential amendments to nine Acts. It also links the low income superannuation tax offset eligibility threshold to the personal income tax threshold and its maximum amount to the superannuation guarantee percentage.", "controversy": {"category": "Cost & economic impact", "summary": "The Tax Institute (21 Jan 2026) said the original 2023 design drew 'considerable criticism from tax professionals and the general public' because balances were not indexed and unrealised capital gains would be taxed, and that the redesigned draft still contained elements that appeared 'inequitable, discriminate among different kinds of superannuation funds, and result in double taxation'; it also criticised a consultation window spanning the holiday period. The Treasurer announced a redesign on 13 Oct 2025; the government says the measure better targets concessions for very large balances.", "raised_by": ["The Tax Institute"], "sources": [{"title": "The Tax Institute - Treasury Laws Amendment (Better Targeted Superannuation Concessions) Bill 2025 submission", "url": "https://www.taxinstitute.com.au/resources/submissions/2026/better-targeted-superannuation-concessions-bill-2025"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31", "public_reaction": {"summary": "YouGov polling for the Australia Institute (6–11 June 2025, n=1,535) found 52% supported and 26% opposed reducing tax concessions on super balances over $3 million, with 22% unsure. A DemosAU poll (31 July 2025, n=1,079) found 45% support and 33% opposition: 59% of Labor voters, 33% of Coalition voters and 28% of One Nation voters in favour. Opposition mobilised through a petition against taxing unrealised gains launched by fund manager Geoff Wilson, which The Australian reported reached 7,600 signatures within two days in June 2025. The Senate inquiry into the original 2023 bill received 42 submissions, almost all from industry bodies and think tanks.", "sources": [{"title": "Super changes popular, especially among voters the Liberals need to win back (The Australia Institute / YouGov)", "url": "https://australiainstitute.org.au/post/super-changes-popular-especially-among-voters-the-liberals-need-to-win-back/", "date": "2025-06-17"}, {"title": "Australians divided on proposed superannuation tax changes (DemosAU)", "url": "https://demosau.com/news/superannuation-tax-changes/", "date": "2025-09-03"}, {"title": "Rush to sign petition against ALP gains tax (The Australian, republished by Wilson Asset Management)", "url": "https://wilsonassetmanagement.com.au/alp-gains-tax/", "date": "2025-06-03"}]}}, {"id": "migration-amendment-2026-measures-no-1-act-2026", "title": "Migration Amendment (2026 Measures No. 1) Bill 2026", "status": "passed", "status_date": "2026-03-13", "status_note": "Introduced 10 Mar 2026; passed both Houses 12 Mar 2026; assented 13 Mar 2026 (Act No. 10 of 2026)", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7447", "legislation_url": "https://www.legislation.gov.au/C2026A00010/latest/text", "summary": "Amends the Migration Act 1958 to enable temporary restrictions on the arrival of specified classes of temporary visa holders, including where events outside Australia increase the risk that visa holders will not depart when their visas cease. The Minister can make an 'arrival control determination' for a specified period.", "controversy": {"category": "Immigration & borders", "summary": "Human Rights Watch (11 Mar 2026) called the bill 'cynical and cruel', saying it would automatically freeze temporary visas, could see travellers in transit detained and deported, and was introduced 'without consultation with Australia's refugee and migration sector' while concentrating power in the Minister. Assistant Minister Julian Hill cited instability in the Middle East and the risk that visa holders would not depart as circumstances changed.", "raised_by": ["Human Rights Watch"], "sources": [{"title": "Australia's Cynical and Cruel Bill to Suspend Temporary Visas (Human Rights Watch)", "url": "https://www.hrw.org/news/2026/03/12/australias-cynical-and-cruel-bill-to-suspend-temporary-visas-0"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "freedom-of-information-amendment-bill-2025", "title": "Freedom of Information Amendment Bill 2025", "status": "failed", "status_date": "2026-03-05", "status_note": "Passed the House 6 Nov 2025; discharged from the Senate Notice Paper 5 Mar 2026 after the government conceded it lacked Senate support; status 'Not Proceeding'", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7371", "legislation_url": null, "summary": "Would have amended the Freedom of Information Act 1982 to implement or respond to recommendations of earlier reviews including the 2013 Hawke Review. Critics reported the bill would have allowed agencies to refuse anonymous requests and requests exceeding a processing-time threshold, introduced an application fee, and expanded exemptions for cabinet and deliberative documents.", "controversy": {"category": "Democratic process", "summary": "The Centre for Public Integrity said the bill 'risked entrenching secrecy and weakening Australia's freedom of information system', with Research Director Gabrielle Appleby noting access to information 'is fundamental to democratic accountability'. A joint release by the Human Rights Law Centre, Alliance for Journalists' Freedom, Australia Institute, Justice and Equity Centre, Grata Fund and Whistleblower Justice Fund (5 Mar 2026) said the bill would have 'increased government secrecy, decreased accountability, and disempowered voters'. The government had argued the changes would address vexatious and resource-intensive requests; Finance Minister Katy Gallagher withdrew the bill citing lack of Senate support.", "raised_by": ["Centre for Public Integrity", "Human Rights Law Centre", "Alliance for Journalists' Freedom", "Australia Institute", "Justice and Equity Centre"], "sources": [{"title": "Withdrawal of FOI Amendment Bill must mark the start of genuine reform (Centre for Public Integrity)", "url": "https://publicintegrity.org.au/withdrawal-of-foi-amendment-bill-must-mark-the-start-of-genuine-reform/"}, {"title": "Joint release: The Albanese Government kills off its own FOI secrecy bill (Justice and Equity Centre)", "url": "https://jec.org.au/focus-areas/civil-rights/joint-release-the-albanese-government-kills-off-its-own-foi-secrecy-bill-in-the-face-of-political-defeat/"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "combatting-antisemitism-hate-and-extremism-criminal-and-migration-laws-act-2026", "title": "Combatting Antisemitism, Hate and Extremism (Criminal and Migration Laws) Bill 2026", "status": "passed", "status_date": "2026-01-20", "status_note": "Introduced and passed both Houses on 20 Jan 2026 in a single sitting day; registered as Act No. 2 of 2026 (assent date not shown on fetched pages). Companion Firearms and Customs Laws Act is Act No. 1 of 2026.", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7422", "legislation_url": "https://www.legislation.gov.au/C2026A00002/latest/text", "summary": "Amends the Criminal Code to create aggravated offences for preachers and leaders who advocate or threaten force or violence and for adults who seek to radicalise children, increase penalties for advocating or threatening violence, create a listing framework for prohibited hate groups, and strengthen prohibited symbols offences. It adds an aggravated sentencing factor for racially motivated conduct and inserts migration character grounds addressing hate-motivated conduct. The package followed the 14 December 2025 Bondi attack.", "controversy": {"category": "Civil liberties & detention", "summary": "Reaction split across the spectrum. The Law Council (15 Jan 2026) warned that 'compressed timelines and limited consultation periods increase the risk of drafting errors', and Human Rights Commission President Hugh de Kretser told the three-day inquiry it was 'insufficient' and that protections should also cover religion, sex, sexuality and disability. Jewish organisations were divided: the Executive Council of Australian Jewry called it 'a significant step in the right direction' while criticising its race-only scope, and the Zionist Federation welcomed the power to ban groups; the Jewish Council of Australia urged a pause, saying 'rushing through sweeping criminal laws is not going to make Jews safer'. Muslim organisations objected: the Australian National Imams Council said it was 'appalled and concerned' the Act could be applied unfairly to Muslims, and the Lebanese Muslim Association said it 'seems to be concentrated to protect one community and target another'. Civil-liberties councils argued 'the Federal Government cannot legislate its way to social cohesion'. The Coalition first called the draft 'pretty unsalvageable' (Sussan Ley) then, after a deal narrowing the hate-group definition and adding a two-yearly review, the Liberals voted for it; the Nationals abstained or voted no, wanting more time, and three of their frontbenchers quit over it. The Greens and Senator David Pocock voted against, citing chilling effects on protest and mandatory minimums. The government said urgent action was needed after the Bondi attack.", "raised_by": ["Law Council of Australia", "Australian Human Rights Commission", "Executive Council of Australian Jewry", "Jewish Council of Australia", "Australian National Imams Council", "Lebanese Muslim Association", "NSW Council for Civil Liberties, Liberty Victoria and QCCL", "Federal Coalition (Sussan Ley; the Nationals)", "Australian Greens", "Senator David Pocock", "Amnesty International Australia"], "sources": [{"title": "Law Council – Combatting Antisemitism, Hate and Extremism Bill", "url": "https://lawcouncil.au/media/news/combatting-antisemitism-hate-and-extremism-bill"}, {"title": "AHRC President's opening statement to the PJCIS inquiry (14 Jan 2026)", "url": "https://humanrights.gov.au/about-us/media-centre/speeches/hugh-de-kretser/parliamentary-joint-committee-on-intelligence-and-security-inquiry-into-the-combatting-antisemitism,-hate-and-extremism-bill-2026-opening-statement"}, {"title": "ECAJ: 'A significant step in the right direction' (13 Jan 2026)", "url": "https://www.ecaj.org.au/a-significant-step-in-the-right-direction/"}, {"title": "Jewish Council of Australia urges pause on 'rushed and dangerous' bill (14 Jan 2026)", "url": "https://www.jewishcouncil.com.au/2026/01/media-release-jewish-council-urges-pause-on-rushed-and-dangerous-hate-speech-bill"}, {"title": "ANIC statement on the legislation (21 Jan 2026)", "url": "https://anic.org.au/anic-appalled-and-deeply-concerned-by-the-combating-antisemitism-hate-and-extremism-legislation/"}, {"title": "ABC: Muslim leaders say hate laws single out their community (16 Jan 2026)", "url": "https://www.abc.net.au/news/2026-01-16/hate-speech-laws-labor-antisemitism-bondi/106231326"}, {"title": "Joint civil-liberties statement (13 Jan 2026)", "url": "https://libertyvictoria.org.au/joint-media-statement-federal-governments-approach-to-building-community-harmony-will-do-real-harm-nsw-council-for-civil-liberties-liberty-victoria-and-queensland-council-for-civil-libert/"}, {"title": "ABC: Hate laws poised to pass after Labor–Liberal deal (20 Jan 2026)", "url": "https://www.abc.net.au/news/2026-01-20/hate-laws-poised-to-pass-after-labor-liberal-deal/106248432"}, {"title": "SBS: Nationals trio break ranks in hate-speech vote (21 Jan 2026)", "url": "https://www.sbs.com.au/news/article/leys-leadership-defied-after-nationals-trio-break-ranks-in-hate-speech-vote/ykhqi4lce"}, {"title": "Greens: will back gun reforms, will not support hate-speech bill (17 Jan 2026)", "url": "https://greens.org.au/news/media-release/greens-will-back-gun-law-reforms-will-not-support-governments-hate-speech-and"}, {"title": "Senator Pocock: amendments on the hate speech and firearm bills", "url": "https://www.davidpocock.com.au/amendments_on_hate_speech_and_firearm_bills"}, {"title": "Amnesty: rushed bill missed the opportunity for broader protections", "url": "https://www.amnesty.org.au/rushed-hate-and-extremism-bill-missed-the-opportunity-for-more-comprehensive-protections-and-lacks-critical-safeguards/"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31", "public_reaction": {"summary": "A Resolve poll for the SMH and Age (17–20 Dec 2025, n=1,010) found 66% supported stronger laws against hate speech based on religion and 76% backed tougher immigration screening for antisemitic views, though only 26% ranked 'tackling hate speech' among their top two priorities for government (49% chose preventing terrorism). The intelligence committee's review of the draft bill received submissions and correspondence 'numbering in the thousands', the majority from individuals raising concerns, 'a very large number' of them describing the hate-speech offences as censorship or fearing that legitimate protest would be criminalised. No major pollster asked directly about the bill itself.", "sources": [{"title": "Labor and Albanese take a hit in post-Bondi Resolve poll (The Conversation)", "url": "https://theconversation.com/labor-and-albanese-take-a-hit-in-post-bondi-resolve-poll-272266", "date": "2026-01-05"}, {"title": "PJCIS report on the exposure draft, Chapter 1: what the public said in submissions", "url": "https://www.aph.gov.au/Parliamentary_Business/Committees/Joint/Intelligence_and_Security/CASHEBILL26/Report/Chapter_1_-_Committee_report", "date": "2026-01"}]}}, {"id": "environment-protection-reform-act-2025", "title": "Environment Protection Reform Bill 2025", "status": "passed", "status_date": "2025-12-01", "status_note": "Passed Senate 27 Nov 2025 with 84 government and 91 Greens amendments; passed both Houses 28 Nov 2025; assented 1 Dec 2025 (Act No. 68 of 2025). Companion National Environmental Protection Agency Act 2025 is Act No. 69 of 2025.", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7398", "legislation_url": "https://www.legislation.gov.au/C2025A00068/latest/text", "summary": "Part of a seven-bill package implementing the 2020 Samuel Review of the EPBC Act. It streamlines assessments and approvals, provides for national environmental standards and bioregional plans, prohibits approval of projects with 'unacceptable impacts', requires residual impacts to be compensated to a net gain, and creates a 'national interest' pathway allowing projects to be approved even if they do not meet certain requirements. A separate Act establishes a National Environmental Protection Agency.", "controversy": {"category": "Environment", "summary": "The Minerals Council of Australia (14 Nov 2025) said the 'unacceptable impacts' test was vague and subjective, that removing existing assessment pathways would push projects into the longest process, and that the new EPA needed clearer accountability to ministers. Environmental law academics writing in The Conversation (27 Nov 2025) criticised the broad 'national interest' exemption, ministerial discretion over standards and the offsets 'restoration fund', while noting the Greens' deal secured native forest protections; the Greens described the outcome as 'woefully short' on climate. The government said the reforms deliver faster, clearer decisions with stronger environmental protection.", "raised_by": ["Minerals Council of Australia", "Australian Greens", "Environmental law academics (The Conversation)"], "sources": [{"title": "Opening statement by MCA CEO Tania Constable to Senate committee", "url": "https://minerals.org.au/resources/opening-statement-by-minerals-council-of-australia-ceo-tania-constable-to-senate-environment-and-communication-legislation-committee/"}, {"title": "Long-sought environmental law reform is finally here. But will the compromise deal actually protect nature? (The Conversation)", "url": "https://theconversation.com/long-sought-environmental-law-reform-is-finally-here-but-will-the-compromise-deal-actually-protect-nature-270775"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31", "public_reaction": {"summary": "The Senate inquiry received 689 published submissions and held four public hearings. The Biodiversity Council's survey (Monash BehaviourWorks, more than 3,500 people, Nov–Dec 2024) found 75% of Australians support strengthening national environmental laws and 75% support national environmental standards with 4% opposed, across party lines (Greens 86%, Labor 82%, Liberal 70%, Nationals 64%). The Australian Conservation Foundation's running petition for strong nature laws and an independent regulator shows 543,576 signatures.", "sources": [{"title": "Senate committee report on the Environment Protection Reform Bill 2025, Chapter 1", "url": "https://www.aph.gov.au/Parliamentary_Business/Committees/Senate/Environment_and_Communications/EPRBill48P/Report/Chapter_1_-_Introduction_and_background", "date": "2026-04"}, {"title": "An increasing majority of Australians back strengthening nature laws (Biodiversity Council)", "url": "https://biodiversitycouncil.org.au/news/an-increasing-majority-of-australians-back-strengthening-nature-laws", "date": "2025-01-31"}, {"title": "Petition for laws that actually protect nature (Australian Conservation Foundation)", "url": "https://www.acf.org.au/environment-laws-petition", "date": "2026-09"}]}}, {"id": "fair-work-amendment-protecting-penalty-and-overtime-rates-act-2025", "title": "Fair Work Amendment (Protecting Penalty and Overtime Rates) Bill 2025", "status": "passed", "status_date": "2025-08-29", "status_note": "Passed both Houses 28 Aug 2025; assented 29 Aug 2025 (Act No. 37 of 2025)", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7335", "legislation_url": "https://www.legislation.gov.au/C2025A00037/latest/text", "summary": "Amends the Fair Work Act 2009 to require the Fair Work Commission to ensure penalty and overtime rates in modern awards are not reduced, and that awards do not include terms substituting for penalty or overtime entitlements where this would reduce the additional pay employees would otherwise receive.", "controversy": {"category": "Workers & business", "summary": "Australian Retailers Association CEO Chris Rodwell called the bill 'heavy-handed regulation' that prevents employees choosing higher base salaries in exchange for penalty rates, and Australian Industry Group CEO Innes Willox said it would 'make it harder for employers to employ people who want to work when it suits them' (Ragtrader, 25 Jul 2025). The government said the bill protects award-reliant workers from having penalty rates traded away.", "raised_by": ["Australian Retailers Association", "Australian Industry Group"], "sources": [{"title": "Retailers berate 'heavy-handed' penalty rates bill (Ragtrader)", "url": "https://www.ragtrader.com.au/news/retailers-berate-heavy-handed-penalty-rates-bill"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "universities-accord-cutting-student-debt-by-20-per-cent-act-2025", "title": "Universities Accord (Cutting Student Debt by 20 Per Cent) Bill 2025", "status": "passed", "status_date": "2025-08-02", "status_note": "First bill of the 48th Parliament; passed both Houses 31 Jul 2025; assented 2 Aug 2025 (Act No. 30 of 2025)", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7342", "legislation_url": "https://www.legislation.gov.au/C2025A00030/latest/text", "summary": "Provides a one-off 20 per cent reduction to HELP and certain other student loan debts incurred on or before 1 June 2025. It raises the minimum repayment threshold from $54,435 to $67,000 for 2025-26 and calculates compulsory repayments on income above the threshold rather than as a percentage of total income.", "controversy": {"category": "Cost & economic impact", "summary": "Andrew Norton, Professor of Higher Education Policy at Monash University (The Conversation, 23 Jul 2025), argued the new repayment system risks a 'debt treadmill' for lower-earning graduates whose repayments fall below indexation, that the 20 per cent cut benefits recent graduates most while future students gain nothing, and that the bill leaves underlying course-cost drivers untouched. The government said the measure delivers immediate cost-of-living relief to three million Australians with student debt.", "raised_by": ["Andrew Norton (Monash University)"], "sources": [{"title": "Labor's new bill would cut HELP loans by 20%. But it also risks locking some graduates into a 'debt treadmill' (The Conversation)", "url": "https://theconversation.com/labors-new-bill-would-cut-help-loans-by-20-but-it-also-risks-locking-some-graduates-into-a-debt-treadmill-261472"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31", "public_reaction": {"summary": "A Resolve poll for the SMH (Oct–Nov 2024, n=1,604) found 54% thought cutting student debts by 20% was a good idea and 27% a bad idea; 71% backed cutting university fees, rising to 77% among 18–34-year-olds. A Change.org petition on HECS indexation started by independent MP Monique Ryan in March 2024 closed with 288,004 supporters. The bill was not referred to a Senate committee, so there is no inquiry submission count.", "sources": [{"title": "Voters back Labor's proposed HECS changes (SMH / Resolve)", "url": "https://www.smh.com.au/politics/federal/voters-back-labor-s-proposed-hecs-changes-they-are-even-keener-for-an-overhaul-of-uni-fees-20241112-p5kpz0.html", "date": "2024-11-12"}, {"title": "Petition: Make our HECS debts easier to pay off (Change.org, Dr Monique Ryan MP)", "url": "https://www.change.org/p/make-our-hecs-debts-easier-to-pay-off", "date": "2024-03-14"}]}}, {"id": "treasury-laws-amendment-better-targeted-superannuation-concessions-bill-2023", "title": "Treasury Laws Amendment (Better Targeted Superannuation Concessions and Other Measures) Bill 2023", "status": "failed", "status_date": "2025-07-21", "status_note": "Passed the House 9 Oct 2024; stalled in the Senate (divided into two bills 28 Nov 2024); lapsed at the end of the 47th Parliament 21 Jul 2025. A redesigned measure was enacted in March 2026 as the Building a Stronger and Fairer Super System Act 2026.", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7133", "legislation_url": null, "summary": "Original 'Division 296' bill that, with an imposition bill, would have applied an additional 15 per cent tax on earnings attributable to superannuation balances above $3 million, calculated on the change in total balance including unrealised gains, with no indexation of the threshold. It also contained unrelated Treasury measures.", "controversy": {"category": "Cost & economic impact", "summary": "The Tax Institute said the original design drew 'considerable criticism from tax professionals and the general public, primarily because the relevant superannuation balances were not indexed, and the measure proposed to tax unrealised capital gains'. The Treasurer announced a redesign on 13 October 2025 that dropped taxation of unrealised gains; the government's rationale was to make concessions on very large balances more sustainable.", "raised_by": ["The Tax Institute"], "sources": [{"title": "The Tax Institute submission on the Better Targeted Superannuation Concessions Bill", "url": "https://www.taxinstitute.com.au/resources/submissions/2026/better-targeted-superannuation-concessions-bill-2025"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31", "public_reaction": {"summary": "YouGov polling for the Australia Institute (6–11 June 2025, n=1,535) found 52% supported and 26% opposed reducing tax concessions on super balances over $3 million, with 22% unsure. A DemosAU poll (31 July 2025, n=1,079) found 45% support and 33% opposition: 59% of Labor voters, 33% of Coalition voters and 28% of One Nation voters in favour. Opposition mobilised through a petition against taxing unrealised gains launched by fund manager Geoff Wilson, which The Australian reported reached 7,600 signatures within two days in June 2025. The Senate inquiry into the original 2023 bill received 42 submissions, almost all from industry bodies and think tanks.", "sources": [{"title": "Super changes popular, especially among voters the Liberals need to win back (The Australia Institute / YouGov)", "url": "https://australiainstitute.org.au/post/super-changes-popular-especially-among-voters-the-liberals-need-to-win-back/", "date": "2025-06-17"}, {"title": "Australians divided on proposed superannuation tax changes (DemosAU)", "url": "https://demosau.com/news/superannuation-tax-changes/", "date": "2025-09-03"}, {"title": "Rush to sign petition against ALP gains tax (The Australian, republished by Wilson Asset Management)", "url": "https://wilsonassetmanagement.com.au/alp-gains-tax/", "date": "2025-06-03"}]}}, {"id": "whistleblower-protection-authority-bill-2025", "title": "Whistleblower Protection Authority Bill 2025", "status": "failed", "status_date": "2025-03-28", "status_note": "Private member's bill (Andrew Wilkie MP) introduced 10 Feb 2025; lapsed at dissolution 28 Mar 2025", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7301", "legislation_url": null, "summary": "Would have established a Whistleblower Protection Authority to receive and facilitate investigation of whistleblower disclosures, support disclosers, investigate mistreatment of whistleblowers and undertake enforcement, with an advisory council and a parliamentary joint committee. The government has not legislated a whistleblower protection authority as at September 2026.", "controversy": null, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "electoral-legislation-amendment-electoral-communications-bill-2024", "title": "Electoral Legislation Amendment (Electoral Communications) Bill 2024", "status": "failed", "status_date": "2025-03-28", "status_note": "Government bill introduced 18 Nov 2024 alongside the Electoral Reform Bill; never debated; lapsed at dissolution 28 Mar 2025. A near-identical private member's bill by Zali Steggall (2025) was removed from the Notice Paper 3 Mar 2026.", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7279", "legislation_url": null, "summary": "Would have prohibited authorising electoral or referendum matter that is inaccurate and misleading to a material extent (including 'deepfakes'), required AI-generated or digitally modified electoral matter to carry a statement to that effect, established an Electoral Communications Panel, and removed the three-day pre-election broadcast 'media blackout'.", "controversy": null, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "electoral-legislation-amendment-electoral-reform-act-2025", "title": "Electoral Legislation Amendment (Electoral Reform) Bill 2024", "status": "passed", "status_date": "2025-02-20", "status_note": "Passed House 20 Nov 2024; stalled in Senate; passed Senate 12 Feb 2025 with 39 government amendments after a Labor-Coalition deal; assented 20 Feb 2025 (Act No. 16 of 2025)", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7280", "legislation_url": "https://www.legislation.gov.au/C2025A00016/latest/text", "summary": "Amends the Commonwealth Electoral Act 1918 to establish annual and overall caps on political gifts, annual caps on electoral expenditure, expedited disclosure of gifts, a lower disclosure threshold, consolidated financial reporting, a new system of administrative funding and increased public election funding. It also introduces the category of 'nominated entity' and expands obligations for Commonwealth campaign accounts.", "controversy": {"category": "Democratic process", "summary": "Independent Senator David Pocock (20 Nov 2024) called the bill a 'major party stitch up' designed to lock out community independents and objected to it not being referred to a Senate inquiry. After the February 2025 Labor-Coalition deal raised the donor cap to $50,000 and the disclosure threshold to $5,000, Greens Senator Larissa Waters said the major parties were 'agreeing on rigging the system to lock out their competitors' and independent MP Kate Chaney said the process showed 'the major parties just do not want any scrutiny' (ABC, 12 Feb 2025). The government said the reforms deliver the first federal caps on donations and spending and end secrecy around donations.", "raised_by": ["Senator David Pocock", "Kate Chaney MP", "Australian Greens (Larissa Waters)"], "sources": [{"title": "Electoral reform desperately needed but changes must be fair for all (Senator David Pocock)", "url": "https://www.davidpocock.com.au/electoral_reform_desperately_needed_but_changes_must_be_fair_for_all"}, {"title": "Labor, Coalition strike deal on electoral reform with watered-down caps and disclosure (ABC News)", "url": "https://www.abc.net.au/news/2025-02-12/labor-coalition-strike-electoral-reform-deal/104928032"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31", "public_reaction": {"summary": "Australia Institute polling (Nov 2024, n=1,009) found 81% of Australians agreed major electoral law changes should first be reviewed by a multi-party committee, with majorities among voters of every party (83% Labor, 83% Coalition, 80% Greens, 66% One Nation), and the Institute's petition demanding an inquiry into the bill shows 35,130 signatures. No inquiry happened: on 19 November 2024 the Senate defeated a motion by Senators Pocock and Lambie to refer the bill to the electoral committee, 18 votes to 38, with Labor, Liberal and National senators all voting no.", "sources": [{"title": "Polling: overwhelming opposition to rushing through political donation laws (The Australia Institute)", "url": "https://australiainstitute.org.au/post/new-polling-reveals-overwhelming-opposition-to-rushing-through-political-donation-laws/", "date": "2024-11-18"}, {"title": "Petition: demand a parliamentary inquiry into the Electoral Reform Bill (The Australia Institute)", "url": "https://nb.australiainstitute.org.au/donations_bill_petition", "date": "2024-11"}, {"title": "Senate vote on referring the bill to a committee, 19 Nov 2024 (They Vote For You)", "url": "https://theyvoteforyou.org.au/divisions/senate/2024-11-19/3", "date": "2024-11-19"}]}}, {"id": "scams-prevention-framework-act-2025", "title": "Scams Prevention Framework Bill 2025", "status": "passed", "status_date": "2025-02-20", "status_note": "Introduced 7 Nov 2024 (as the 2024 bill); passed both Houses 13 Feb 2025; assented 20 Feb 2025 (Act No. 15 of 2025)", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7275", "legislation_url": "https://www.legislation.gov.au/C2025A00015/latest/text", "summary": "Amends the Competition and Consumer Act 2010 to establish a Scams Prevention Framework requiring service providers in designated sectors (initially banks, telecommunications providers and digital platforms) to take steps to prevent, detect, report, disrupt and respond to scams using their services, with penalties for non-compliance and dispute resolution arrangements.", "controversy": {"category": "Other", "summary": "A coalition of consumer groups including Consumer Action Law Centre, CHOICE, ACCAN, Financial Rights Legal Centre and Financial Counselling Australia (8 Oct 2024) said the framework 'only goes halfway' because it lacks a UK-style presumption of reimbursement for scam victims; Consumer Action's Stephanie Tonkin said victims could face 'an almost 30-step process' taking up to two years with no guaranteed refund. The government's stated position was that a reimbursement-based model would reduce incentives for consumers and industry to prevent scams.", "raised_by": ["Consumer Action Law Centre", "CHOICE", "Australian Communications Consumer Action Network", "Financial Rights Legal Centre", "Financial Counselling Australia"], "sources": [{"title": "Government's Scams Prevention Framework only goes halfway - we need a presumption of reimbursement (Consumer Action Law Centre)", "url": "https://consumeraction.org.au/governments-scams-prevention-framework-only-goes-halfway-we-need-a-presumption-of-reimbursement-say-consumer-advocates/"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "early-childhood-education-and-care-three-day-guarantee-act-2025", "title": "Early Childhood Education and Care (Three Day Guarantee) Bill 2025", "status": "passed", "status_date": "2025-02-20", "status_note": "Introduced 5 Feb 2025; passed both Houses 13 Feb 2025; assented 20 Feb 2025 (Act No. 12 of 2025)", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7316", "legislation_url": "https://www.legislation.gov.au/C2025A00012/latest/text", "summary": "Replaces the Child Care Subsidy activity test with a guaranteed minimum of 72 hours per fortnight (three days a week) of subsidised early childhood education and care for all families regardless of work or study hours, and a 100-hour fortnightly entitlement for families caring for an Aboriginal or Torres Strait Islander child.", "controversy": null, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "criminal-code-amendment-hate-crimes-act-2025", "title": "Criminal Code Amendment (Hate Crimes) Bill 2025", "status": "passed", "status_date": "2025-02-07", "status_note": "Introduced Sep 2024 as the Hate Crimes Bill 2024; passed both Houses 6 Feb 2025 with 20 government and 4 opposition amendments adding mandatory minimum sentences; assented 7 Feb 2025 (Act No. 1 of 2025)", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7240", "legislation_url": "https://www.legislation.gov.au/C2025A00001/latest/text", "summary": "Amends the Criminal Code to strengthen offences for urging force or violence against targeted groups, create new offences for threatening force or violence against groups or their members, and expand the groups protected by the prohibited hate symbols offences. Government amendments agreed on 6 February 2025 introduced mandatory minimum sentences, including 12 months' imprisonment for public display of prohibited symbols and six years for terrorism offences.", "controversy": {"category": "Due process & sentencing", "summary": "The Law Council of Australia (6 Feb 2025) said it was 'extremely disappointed' by the late addition of mandatory minimums, with President Juliana Warner arguing they prevent courts considering personal circumstances so that, for example, a person displaying a prohibited symbol at a protest would face 12 months' jail, and noting the amendments contradicted Labor's 2023 national platform. Greens Leader Adam Bandt said 'we have very real concerns with mandatory minimum sentencing' (ABC, 5 Feb 2025). Home Affairs Minister Tony Burke said delay 'does come at a cost' given crimes 'happening in real time'.", "raised_by": ["Law Council of Australia", "Australian Greens (Adam Bandt)"], "sources": [{"title": "Mandatory sentencing is not the answer (Law Council of Australia)", "url": "https://lawcouncil.au/media/media-releases/mandatory-sentencing-is-not-the-answer"}, {"title": "Labor backs mandatory sentences for terror and hate crimes amid Coalition pressure (ABC News)", "url": "https://www.abc.net.au/news/2025-02-05/labor-to-implement-mandatory-minimum-sentences-for-hate-crimes/104902500"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31", "public_reaction": {"summary": "No published poll, parliamentary e-petition or public petition specifically on this bill or its mandatory minimum sentences was found. The Senate inquiry received 40 submissions, almost all from organisations (including the Executive Council of Australian Jewry, the Human Rights Commission, the NSW Council for Civil Liberties, the Islamic Council of Victoria and the Australian Christian Lobby) with only a handful from individuals.", "sources": [{"title": "Submissions to the Senate inquiry into the Hate Crimes Bill (40 items)", "url": "https://www.aph.gov.au/Parliamentary_Business/Committees/Senate/Legal_and_Constitutional_Affairs/HateCrimes47/Submissions", "date": "2025-02"}]}}, {"id": "nature-positive-environment-protection-australia-bill-2024", "title": "Nature Positive (Environment Protection Australia) Bill 2024", "status": "failed", "status_date": "2025-02-05", "status_note": "Passed the House 4 Jul 2024; discharged from the Senate Notice Paper 5 Feb 2025 after the Prime Minister said the government would not proceed 'this term'; status 'Not Proceeding'. Replaced by the Environment Protection Reform Act 2025 and National Environmental Protection Agency Act 2025.", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7192", "legislation_url": null, "summary": "Would have established Environment Protection Australia as a statutory Commonwealth regulator to undertake regulatory and implementation functions under federal environmental laws, as 'stage 2' of the Nature Positive reforms. Companion bills would have created Environment Information Australia and made transitional amendments.", "controversy": {"category": "Environment", "summary": "ABC reported (2 Feb 2025) that the bills were shelved after resistance from WA Premier Roger Cook and sections of the mining industry, with Prime Minister Anthony Albanese saying he could not see a 'path to success' and 'we won't be proceeding with it this term'. Greens environment spokesperson Sarah Hanson-Young said 'the prime minister has again caved to the vested interests of the WA mining industry'. The government said it would revisit the reforms after the election.", "raised_by": ["Australian Greens (Sarah Hanson-Young)", "WA Government (Roger Cook)", "Mining industry groups"], "sources": [{"title": "Labor shelves contentious 'nature positive' laws after West Australian backlash (ABC News)", "url": "https://www.abc.net.au/news/2025-02-02/labor-shelves-contentious-nature-positive-laws/104886608"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31", "public_reaction": {"summary": "The Senate inquiry published 209 submissions and received about 180 more plus over 3,670 campaign emails from individuals, with one public hearing (26 July 2024). YouGov polling for ACF and WWF-Australia (Aug 2024) found 86% of Australians support stronger national nature laws and seven in ten said the government needs to do more for nature. A RedBridge poll of more than 1,500 WA voters (Nov 2024) found 75% supported a federal environmental regulator independent of government.", "sources": [{"title": "Senate committee report on the Nature Positive bills, Chapter 1", "url": "https://www.aph.gov.au/Parliamentary_Business/Committees/Senate/Environment_and_Communications/NaturePositivebills/Report/Chapter_1_-_Introduction", "date": "2024-09"}, {"title": "New polling shows overwhelming support for stronger nature laws (ACF / YouGov)", "url": "https://www.acf.org.au/news/new-polling-shows-overwhelming-support-for-stronger-nature-laws", "date": "2024-08-10"}, {"title": "WA poll on a federal EPA (Conservation Council of WA / RedBridge)", "url": "https://www.ccwa.org.au/epbc_reform", "date": "2024-11-27"}]}}, {"id": "online-safety-amendment-social-media-minimum-age-act-2024", "title": "Online Safety Amendment (Social Media Minimum Age) Bill 2024", "status": "passed", "status_date": "2024-12-10", "status_note": "Introduced 21 Nov 2024; passed both Houses 29 Nov 2024 with 8 government amendments; assented 10 Dec 2024 (Act No. 127 of 2024); minimum-age obligations commenced 10 Dec 2025", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7284", "legislation_url": "https://www.legislation.gov.au/C2024A00127/latest/text", "summary": "Amends the Online Safety Act 2021 to establish a minimum age of 16 for social media use and to oblige providers of age-restricted social media platforms to take reasonable steps to prevent under-16s from holding accounts. It also makes a consequential amendment to the Age Discrimination Act 2004.", "controversy": {"category": "Privacy & anonymity", "summary": "The Law Council of Australia said the Senate inquiry's one-day submission window was 'highly concerning' and wrote to senators (26 Nov 2024) raising the 'extremely broad' definition of age-restricted platform, potential over-collection of personal information and the reliance on subsequent rules. Amnesty International Australia (26 Nov 2024) warned age verification could force platforms to collect biometric or identity data and that a blanket ban would isolate young people rather than regulate platforms. The government said the law responds to parents' concerns and puts the onus on platforms rather than children.", "raised_by": ["Law Council of Australia", "Amnesty International Australia"], "sources": [{"title": "Law Council of Australia - Online Safety Amendment (Social Media Minimum Age) Bill 2024", "url": "https://lawcouncil.au/resources/submissions/online-safety-amendment-social-media-minimum-age-bill-2024"}, {"title": "Amnesty International Australia submission to the inquiry", "url": "https://www.amnesty.org.au/submission-inquiry-into-social-media-minimun-age/"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31", "public_reaction": {"summary": "YouGov (15–21 Nov 2024, n=1,515) found 77% of Australians supported the under-16 ban and 23% opposed, up from 61% in August 2024. A Resolve poll for the SMH (Dec 2024) put support at 58% and opposition at 18%, with 62% of parents in favour, but 68% did not expect the ban to work. The one-day Senate inquiry received about 15,000 submissions, most of them variants of a template response after Elon Musk criticised the bill on X.", "sources": [{"title": "Support for under-16 social media ban soars to 77% (YouGov)", "url": "https://yougov.com/articles/51000-support-for-under-16-social-media-ban-soars-to-77-among-australians", "date": "2024-11-26"}, {"title": "Australians like banning teens from social media. They just don't think it'll work (SMH / Resolve)", "url": "https://www.smh.com.au/politics/federal/australians-like-banning-teens-from-social-media-they-just-don-t-think-it-ll-work-20241210-p5kx9l.html", "date": "2024-12-10"}, {"title": "Inquiry flooded with 15,000 submissions after Elon Musk weighs in (ABC News)", "url": "https://www.abc.net.au/news/2024-11-25/social-media-age-ban-inquiry-flooded-with-submissions/104644208", "date": "2024-11-25"}]}}, {"id": "privacy-and-other-legislation-amendment-act-2024", "title": "Privacy and Other Legislation Amendment Bill 2024", "status": "passed", "status_date": "2024-12-10", "status_note": "Passed both Houses 29 Nov 2024 with 35 government amendments; assented 10 Dec 2024 (Act No. 128 of 2024)", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7249", "legislation_url": "https://www.legislation.gov.au/C2024A00128/latest/text", "summary": "First tranche of Privacy Act reform. Expands the Information Commissioner's powers, enables information sharing after data breaches and in emergencies, requires a Children's Online Privacy Code, adds transparency obligations for automated decisions, and introduces new civil penalties. It also creates a statutory tort for serious invasions of privacy and Criminal Code offences for 'doxxing'.", "controversy": {"category": "Privacy & anonymity", "summary": "The Law Council of Australia (7 Nov 2024) supported passage but called for a government roadmap with timeframes for the remaining Privacy Act Review reforms, sought redrafting of the statutory tort so its parameters were clearer, and warned the doxxing offences were 'drafted too broadly' with unclear definitions of 'menacing' and 'harassing'. The government described the bill as a first step, with further tranches to follow.", "raised_by": ["Law Council of Australia"], "sources": [{"title": "Law Council of Australia - Privacy and Other Legislation Amendment Bill 2024", "url": "https://lawcouncil.au/media/news/privacy-and-other-legislation-amendment-bill-2024"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "future-made-in-australia-act-2024", "title": "Future Made in Australia Bill 2024", "status": "passed", "status_date": "2024-12-10", "status_note": "Passed both Houses 29 Nov 2024; assented 10 Dec 2024 (Act No. 119 of 2024). Related Production Tax Credits Act (hydrogen and critical minerals) assented 14 Feb 2025 (Act No. 9 of 2025).", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7219", "legislation_url": "https://www.legislation.gov.au/C2024A00119/latest/text", "summary": "Establishes the National Interest Framework to guide public investment intended to facilitate private-sector investment in priority industries such as renewable hydrogen, critical minerals processing and clean energy manufacturing. It sets out sector assessment processes and community benefit principles for Future Made in Australia support.", "controversy": {"category": "Cost & economic impact", "summary": "Productivity Commission chair Danielle Wood (ABC, 25 Apr 2024) said 'we need to be very cautious about stepping into this space', warned that subsidised infant industries 'turn into very hungry teenagers and it's kind of hard to turn off the tap', and said there was 'nothing wrong with buying cheaper solar panels from China'. The government argued the 'world has changed' and Australia risked being left behind in the global competition for clean-energy manufacturing; the Commission later welcomed added scrutiny provisions in the bill.", "raised_by": ["Productivity Commission (Danielle Wood)"], "sources": [{"title": "The government's plan for a future 'made in Australia' has failed to win over the productivity commissioner (ABC News)", "url": "https://www.abc.net.au/news/2024-04-25/productivity-commissioner-government-future-made-australia/103763714"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "help-to-buy-act-2024", "title": "Help to Buy Bill 2023", "status": "passed", "status_date": "2024-12-10", "status_note": "Introduced 30 Nov 2023; deferred in the Senate in Sep 2024 by the Coalition and Greens (a duplicate 'No. 2' bill was introduced as a potential double-dissolution trigger and lapsed); passed both Houses 27 Nov 2024; assented 10 Dec 2024 (Act No. 124 of 2024)", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7123", "legislation_url": "https://www.legislation.gov.au/C2024A00124/latest/text", "summary": "Establishes the Help to Buy shared equity scheme, administered by Housing Australia, under which the Commonwealth takes an equity stake to help low- and middle-income earners purchase new or existing homes with a smaller deposit. A companion Act makes consequential amendments.", "controversy": {"category": "Cost & economic impact", "summary": "The Greens and Coalition withheld Senate support for months; the Greens argued the scheme would push up prices and demanded action on rent caps and negative gearing, with housing spokesperson Max Chandler-Mather saying Labor 'would rather have a fight with the Greens than actually help people' (Michelle Grattan, The Conversation, 25 Nov 2024). The government said the scheme would help 40,000 households into home ownership and refused to negotiate broader housing tax changes.", "raised_by": ["Australian Greens", "Federal Opposition"], "sources": [{"title": "Greens capitulate, announcing they will 'wave through' Labor's Help to Buy and Build to Rent housing bills (The Conversation)", "url": "https://theconversation.com/greens-capitulate-announcing-they-will-wave-through-labors-help-to-buy-and-build-to-rent-housing-bills-244513"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31", "public_reaction": {"summary": "No published poll, e-petition or public petition specifically on the Help to Buy shared-equity scheme was found. The Senate Economics inquiry received 14 submissions and held one public hearing (5 March 2024), almost all from industry and housing organisations rather than individuals.", "sources": [{"title": "Senate Economics Legislation Committee report on the Help to Buy Bills", "url": "https://www.aph.gov.au/Parliamentary_Business/Committees/Senate/Economics/HelptoBuyBills2023/Report", "date": "2024-04"}]}}, {"id": "migration-amendment-removal-and-other-measures-act-2024", "title": "Migration Amendment (Removal and Other Measures) Bill 2024", "status": "passed", "status_date": "2024-12-04", "status_note": "Passed House in one day on 26 Mar 2024; stalled in Senate; passed Senate 28 Nov 2024 with 11 government amendments; assented 4 Dec 2024 (Act No. 107 of 2024)", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7179", "legislation_url": "https://www.legislation.gov.au/C2024A00107/latest/text", "summary": "Amends the Migration Act 1958 to require non-citizens on a removal pathway who have exhausted avenues to remain in Australia to cooperate with steps to arrange their removal, with criminal penalties for non-compliance. It also allows the Minister to designate 'removal concern countries' whose nationals may be refused visas.", "controversy": {"category": "Immigration & borders", "summary": "The Kaldor Centre for International Refugee Law (26 Mar 2024) said the bill gave the Minister 'extraordinarily broad and ill-defined powers', imposed mandatory prison terms of one to five years for non-cooperation that were 'unprecedented in Australian law', and could see entire countries subject to visa bans. Human Rights Watch (28 Nov 2024) said the laws 'criminalise administrative non-compliance'. The government said the powers were needed to remove people with no right to remain, following High Court decisions on indefinite detention.", "raised_by": ["Kaldor Centre for International Refugee Law (UNSW)", "Human Rights Watch"], "sources": [{"title": "Kaldor Centre statement on new migration bill (UNSW)", "url": "https://www.unsw.edu.au/news/2024/03/Kaldor-Centre-statement-deportation-bill"}, {"title": "Australia Passes Harsh New Anti-Migration Laws (Human Rights Watch)", "url": "https://www.hrw.org/news/2024/11/28/australia-passes-harsh-new-anti-migration-laws"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31", "public_reaction": {"summary": "Essential Research polling (26 Feb 2024, n=1,145) found 59% agreed 'the government is moving too slowly to place former detainees back in detention' and 51% agreed 'the Albanese government is losing control of its borders' (21% disagreed). Opposition to the bills came mainly through submissions and petitions: the Senate inquiry into the Removal Bill lists 318 submissions (121 from organisations and a large volume from individuals), the three-day November 2024 inquiry into the Migration Amendment Bill received 114 submissions, and a Change.org movement page against the Removal Bill shows three petitions with 15,180 supporters combined. No poll specifically on the deportation or third-country powers was found.", "sources": [{"title": "Attitudes to asylum seeker statements (Essential Report)", "url": "https://essentialreport.com.au/questions/attitudes-to-asylum-seeker-statements", "date": "2024-02-26"}, {"title": "Submissions to the Senate inquiry into the Removal and Other Measures Bill (318 items)", "url": "https://www.aph.gov.au/Parliamentary_Business/Committees/Senate/Legal_and_Constitutional_Affairs/MigrationAmendment24/Submissions", "date": "2024-05"}, {"title": "Senate committee report on the Migration Amendment Bill 2024, Chapter 1", "url": "https://www.aph.gov.au/Parliamentary_Business/Committees/Senate/Legal_and_Constitutional_Affairs/MigrationAmendment47/Report/Chapter_1_-_Introduction", "date": "2024-11-26"}, {"title": "Petitions against the Migration Amendment Bill 2024 (Change.org)", "url": "https://www.change.org/m/the-migration-amendment-bill-2024", "date": "2024"}]}}, {"id": "migration-amendment-act-2024", "title": "Migration Amendment Bill 2024", "status": "passed", "status_date": "2024-12-04", "status_note": "Introduced 7 Nov 2024; passed both Houses 28 Nov 2024 with Coalition support; assented 4 Dec 2024 (Act No. 105 of 2024). Passed alongside the Prohibiting Items in Immigration Detention Facilities Act (Act No. 106 of 2024), which expanded search and seizure powers including over mobile phones.", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7276", "legislation_url": "https://www.legislation.gov.au/C2024A00105/latest/text", "summary": "Amends the Migration Act 1958 to end certain bridging visas where the holder has permission to enter another country, allow the Minister to decide a protection finding would no longer be made for a 'removal pathway non-citizen', create an immunity from civil liability for certain acts, permit disclosure of criminal history information to foreign countries, and authorise spending on 'third country reception arrangements'.", "controversy": {"category": "Immigration & borders", "summary": "The Human Rights Law Centre recommended the bill not be passed, arguing that 'warehousing people in third countries has never been, and will never be, an acceptable or effective response' and that reversing protection findings undermined refugee determinations. Human Rights Watch (28 Nov 2024) noted receiving countries need not be Refugee Convention parties and described the package as 'a new low'. The Refugee Council of Australia said of the companion phones bill that 'mobile phones are a lifeline for people in detention'. The government said the measures respond to the High Court's NZYQ and YBFZ decisions and protect community safety.", "raised_by": ["Human Rights Law Centre", "Human Rights Watch", "Refugee Council of Australia"], "sources": [{"title": "Submission to Migration Amendment Bill 2024 (Human Rights Law Centre)", "url": "https://www.hrlc.org.au/submissions/2024-11-21-migration-amendment/"}, {"title": "Australia Passes Harsh New Anti-Migration Laws (Human Rights Watch)", "url": "https://www.hrw.org/news/2024/11/28/australia-passes-harsh-new-anti-migration-laws"}, {"title": "Refugee Council alarmed by new bill to expand search and seizure powers in immigration detention", "url": "https://www.refugeecouncil.org.au/new-bill-search-and-seizure-powers-immigration-detention/"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31", "public_reaction": {"summary": "Essential Research polling (26 Feb 2024, n=1,145) found 59% agreed 'the government is moving too slowly to place former detainees back in detention' and 51% agreed 'the Albanese government is losing control of its borders' (21% disagreed). Opposition to the bills came mainly through submissions and petitions: the Senate inquiry into the Removal Bill lists 318 submissions (121 from organisations and a large volume from individuals), the three-day November 2024 inquiry into the Migration Amendment Bill received 114 submissions, and a Change.org movement page against the Removal Bill shows three petitions with 15,180 supporters combined. No poll specifically on the deportation or third-country powers was found.", "sources": [{"title": "Attitudes to asylum seeker statements (Essential Report)", "url": "https://essentialreport.com.au/questions/attitudes-to-asylum-seeker-statements", "date": "2024-02-26"}, {"title": "Submissions to the Senate inquiry into the Removal and Other Measures Bill (318 items)", "url": "https://www.aph.gov.au/Parliamentary_Business/Committees/Senate/Legal_and_Constitutional_Affairs/MigrationAmendment24/Submissions", "date": "2024-05"}, {"title": "Senate committee report on the Migration Amendment Bill 2024, Chapter 1", "url": "https://www.aph.gov.au/Parliamentary_Business/Committees/Senate/Legal_and_Constitutional_Affairs/MigrationAmendment47/Report/Chapter_1_-_Introduction", "date": "2024-11-26"}, {"title": "Petitions against the Migration Amendment Bill 2024 (Change.org)", "url": "https://www.change.org/m/the-migration-amendment-bill-2024", "date": "2024"}]}}, {"id": "aged-care-act-2024", "title": "Aged Care Bill 2024", "status": "passed", "status_date": "2024-12-02", "status_note": "Passed both Houses 25 Nov 2024 with extensive government, opposition and crossbench amendments; assented 2 Dec 2024 (Act No. 104 of 2024); commenced 1 Nov 2025", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7238", "legislation_url": "https://www.legislation.gov.au/C2024A00104/latest/text", "summary": "Establishes a new framework for Commonwealth-funded aged care in response to the Royal Commission and the Aged Care Taskforce, including a Statement of Rights, new provider registration and regulatory arrangements, the 'Support at Home' program, means-tested co-contributions for non-clinical care, and a First Nations Aged Care Commissioner.", "controversy": {"category": "Cost & economic impact", "summary": "The Australian Greens issued a dissenting report to the Senate inquiry and, in later statements, Senator Penny Allman-Payne said older Australians would face co-payments of 'up to $50 per shower' under Support at Home and that the government had embedded aged care 'as a marketplace' rather than a universal entitlement. The Coalition supported passage subject to amendments it negotiated. The government said the co-contribution model, based on the Aged Care Taskforce, makes the system sustainable while fully funding clinical care.", "raised_by": ["Australian Greens (Penny Allman-Payne)"], "sources": [{"title": "Labor backs in continued shortages of aged care, $50 showers (Australian Greens)", "url": "https://greens.org.au/news/media-release/labor-backs-continued-shortages-aged-care-50-showers-senate-inquiry-report-urges"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "treasury-laws-amendment-reserve-bank-reforms-act-2024", "title": "Treasury Laws Amendment (Reserve Bank Reforms) Bill 2023", "status": "passed", "status_date": "2024-11-29", "status_note": "Introduced 29 Nov 2023; passed Senate 28 Nov 2024 with 3 Greens amendments after the Coalition withdrew support; passed both Houses and assented 29 Nov 2024 (Act No. 96 of 2024); commenced 1 Mar 2025", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7126", "legislation_url": "https://www.legislation.gov.au/C2024A00096/latest/text", "summary": "Implements part of the government's response to the RBA Review by replacing the Reserve Bank Board with a separate Monetary Policy Board and Governance Board and clarifying the RBA's objectives. As introduced it removed the Treasurer's power to override monetary policy decisions, but Greens amendments retained that power and the RBA's power to direct bank lending.", "controversy": {"category": "Other", "summary": "Shadow Treasurer Angus Taylor withdrew the Coalition from a bipartisan deal, arguing the reform would let the Treasurer 'stack' the new monetary policy board with favourable appointees (Michelle Grattan, The Conversation, 10 Sep 2024). The Greens conditioned support on retaining the Treasurer's override power, which the government accepted. Treasurer Jim Chalmers said he had accommodated six opposition requests and that the reforms implement the independent RBA Review.", "raised_by": ["Federal Opposition (Angus Taylor)", "Australian Greens"], "sources": [{"title": "Coalition torpedoes bipartisan deal on Reserve Bank monetary policy board (The Conversation)", "url": "https://theconversation.com/coalition-torpedoes-bipartisan-deal-on-reserve-bank-monetary-policy-board-238685"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "communications-legislation-amendment-combatting-misinformation-and-disinformation-bill-2024", "title": "Communications Legislation Amendment (Combatting Misinformation and Disinformation) Bill 2024", "status": "failed", "status_date": "2024-11-25", "status_note": "Passed the House 7 Nov 2024; on 24 Nov 2024 the Minister announced the government would not proceed as there was 'no pathway to legislate this proposal through the Senate'; discharged from the Senate Notice Paper 25 Nov 2024", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7239", "legislation_url": null, "summary": "Would have amended the Broadcasting Services Act 1992 to impose obligations on digital platforms regarding content 'reasonably verifiable as false, misleading or deceptive' and reasonably likely to cause serious harm, and expanded the Australian Communications and Media Authority's powers to make and enforce codes and standards on misinformation and disinformation. The government said it would have required platforms to publish risk assessments and provide complaints processes.", "controversy": {"category": "Free speech", "summary": "Shadow Communications Minister David Coleman called the bill 'appalling' and warned platforms would censor content 'to avoid the threat of big fines'; the Greens opposed it citing 'broad, ambiguous definitions' that would leave platforms to determine truth; the Institute of Public Affairs argued it would 'silence online debate' (ACS Information Age, 25 Nov 2024). Minister Michelle Rowland said the bill would have delivered 'an unprecedented level of transparency, holding big tech to account' and that the government would pursue other measures such as truth in political advertising and deepfake offences.", "raised_by": ["Federal Opposition (David Coleman)", "Australian Greens", "Institute of Public Affairs"], "sources": [{"title": "Minister's statement on the Combatting Misinformation and Disinformation Bill 2024 (24 Nov 2024)", "url": "https://minister.infrastructure.gov.au/rowland/media-release/communications-legislation-amendment-combatting-misinformation-and-disinformation-bill-2024"}, {"title": "Government limps away from 'dangerous' disinformation bill (ACS Information Age)", "url": "https://ia.acs.org.au/article/2024/government-limps-away-from--dangerous--disinformation-bill.html"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31", "public_reaction": {"summary": "The 2023 consultation on the draft drew 2,418 public submissions plus about 20,000 short-form comments, more than 24,000 responses in total, with the department's published sample dominated by free-speech and censorship objections. The 2024 Senate inquiry published 105 submissions and also received more than 8,000 contributions from individuals and a further 22,000 through organised campaigns; a Change.org petition against the bill gathered 2,568 signatures. No poll from a major pollster on the bill was found.", "sources": [{"title": "Consultation outcome: new ACMA powers to combat misinformation and disinformation (Department of Infrastructure and Communications)", "url": "https://www.infrastructure.gov.au/have-your-say/new-acma-powers-combat-misinformation-and-disinformation", "date": "2023-08"}, {"title": "Senate committee report, Chapter 1 (submission numbers)", "url": "https://www.aph.gov.au/Parliamentary_Business/Committees/Senate/Environment_and_Communications/MisandDisinfobill/Report/Chapter_1_-_Introduction", "date": "2024-11"}, {"title": "Petition: Stop the Misinformation and Disinformation Bill (Change.org)", "url": "https://www.change.org/p/protect-australia-s-free-speech-stop-the-misinformation-and-disinformation-bill", "date": "2024-09"}]}}, {"id": "treasury-laws-amendment-cost-of-living-tax-cuts-act-2024", "title": "Treasury Laws Amendment (Cost of Living Tax Cuts) Bill 2024", "status": "passed", "status_date": "2024-03-05", "status_note": "Introduced 6 Feb 2024; passed both Houses 27 Feb 2024; assented 5 Mar 2024 (Act No. 3 of 2024); applies from 1 Jul 2024", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7140", "legislation_url": "https://www.legislation.gov.au/C2024A00003/latest/text", "summary": "Amends the Income Tax Rates Act 1986 to modify individual income tax thresholds and rates from 2024-25, redesigning the previously legislated 'stage 3' tax cuts to reduce the 19 per cent rate to 16 per cent, reduce the 32.5 per cent rate to 30 per cent, and adjust the thresholds for the 37 and 45 per cent rates.", "controversy": {"category": "Democratic process", "summary": "Opposition Leader Peter Dutton said the Prime Minister had broken a repeated pre-election commitment to deliver the legislated stage 3 cuts unchanged and 'should call an election and put the changed position to the Australian people' (ABC, 26 Jan 2024); the Coalition ultimately voted for the bill. The government said changed economic circumstances justified redirecting relief to low- and middle-income earners, with Treasury advising 13.6 million taxpayers would benefit.", "raised_by": ["Federal Opposition (Peter Dutton)"], "sources": [{"title": "The government's stage 3 tax cuts decision raises the stakes for Albanese (ABC News)", "url": "https://www.abc.net.au/news/2024-01-26/government-stage-3-tax-cuts-albanese-stakes-raised-dutton/103390386"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31", "public_reaction": {"summary": "Newspoll (31 Jan–3 Feb 2024, n=1,245) found 62% thought the government did the right thing by reworking the stage 3 tax cuts and 29% said it should have kept its promise. Guardian Essential polling (24–28 Jan 2024, n=1,201) had 47% backing the revised cuts, 22% wanting the original cuts kept, 19% preferring deferral for those earning over $200,000 and 13% cancellation. Australia Institute polling (23–29 Jan 2024, n=1,017) found 58% preferred restructuring the cuts and 65% said adapting economic policy matters more than keeping an election promise. Roy Morgan recorded a two-point fall in Labor's two-party vote in the week the promise was broken.", "sources": [{"title": "Newspoll: 62% support stage three changes (The Conversation)", "url": "https://theconversation.com/labors-newspoll-lead-unchanged-since-december-as-62-support-stage-three-changes-222257", "date": "2024-02-05"}, {"title": "Polling: stage 3 tax cuts and election promises (The Australia Institute)", "url": "https://australiainstitute.org.au/report/polling-stage-3-tax-cuts-and-election-promises/", "date": "2024-01-31"}, {"title": "ALP support falls 2% after breaking promise on stage 3 tax cuts (Roy Morgan)", "url": "https://www.roymorgan.com/findings/9449-federal-voting-intention-january-29-2024", "date": "2024-01-29"}]}}, {"id": "fair-work-legislation-amendment-closing-loopholes-no-2-act-2024", "title": "Fair Work Legislation Amendment (Closing Loopholes No. 2) Bill 2023", "status": "passed", "status_date": "2024-02-26", "status_note": "Created when the Senate split the Closing Loopholes Bill 2023 on 7 Dec 2023 (the first part, including wage theft and labour hire measures, became Act No. 120 of 2023 on 14 Dec 2023); passed both Houses 12 Feb 2024 with Greens, Lambie, Pocock and Thorpe amendments; assented 26 Feb 2024 (Act No. 2 of 2024)", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7134", "legislation_url": "https://www.legislation.gov.au/C2024A00002/latest/text", "summary": "Amends the Fair Work Act 2009 on casual employment, the definition of employment, sham contracting, workplace delegates' rights, intractable bargaining, and minimum standards for 'employee-like' gig workers and road transport contractors. A Greens amendment agreed in the Senate inserted a 'right to disconnect' allowing employees to refuse unreasonable out-of-hours contact.", "controversy": {"category": "Workers & business", "summary": "ACCI chief executive Andrew McKellar said there was 'a fundamental flaw' in the process, with '89 new amendments being brought forth on top of 800 pages of existing legislation that was rammed through', and Business Council chief executive Bran Black said the amendments made 'a bad bill worse' and would make casual jobs harder to find (AAP, 29 Nov 2023). Employment Minister Tony Burke said the changes were 'pragmatic, practical' and would deliver better workplace protection.", "raised_by": ["Australian Chamber of Commerce and Industry", "Business Council of Australia", "Minerals Council of Australia"], "sources": [{"title": "Businesses slam workplace changes as bill clears House (AAP)", "url": "https://aapnews.aap.com.au/news/business-groups-slam-workplace-law-amendments"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "counter-terrorism-legislation-amendment-prohibited-hate-symbols-and-other-measures-act-2023", "title": "Counter-Terrorism Legislation Amendment (Prohibited Hate Symbols and Other Measures) Bill 2023", "status": "passed", "status_date": "2023-12-11", "status_note": "Introduced 14 Jun 2023; passed both Houses 6 Dec 2023 with 34 government amendments; assented 11 Dec 2023 (Act No. 113 of 2023)", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7048", "legislation_url": "https://www.legislation.gov.au/C2023A00113/latest/text", "summary": "Creates Commonwealth offences for publicly displaying or trading in goods bearing prohibited Nazi and Islamic State symbols, and for using a carriage service for violent extremist material. It expands the offence of advocating terrorism to cover instructing on or praising a terrorist act, raises its maximum penalty from 5 to 7 years, and removes the sunsetting requirement for terrorist organisation listings.", "controversy": null, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "constitution-alteration-aboriginal-and-torres-strait-islander-voice-2023", "title": "Constitution Alteration (Aboriginal and Torres Strait Islander Voice) 2023", "status": "failed", "status_date": "2023-10-14", "status_note": "Passed both Houses by absolute majority 19 Jun 2023; the proposal was not approved at the referendum on 14 Oct 2023 (aph.gov.au status: 'Passed Both Houses'; the alteration did not take effect)", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r7019", "legislation_url": null, "summary": "Proposed to alter the Constitution to recognise Aboriginal and Torres Strait Islander peoples as the First Peoples of Australia by establishing a Voice to make representations to the Parliament and the Executive Government on matters relating to Aboriginal and Torres Strait Islander peoples. As a constitutional alteration it required approval at a referendum, where it was rejected nationally and in every state.", "controversy": {"category": "Indigenous rights", "summary": "Researchers Andrea Carson, Rebecca Strating and Simon Jackman (The Conversation, 1 May 2024) found support collapsed after the Opposition Leader rejected the proposal, with the No campaign using messages such as 'the vote will divide us' and 'if you don't know, vote no', and identified cost-of-living concerns and a 'disinformation ecosystem' as further factors. The government argued the Voice was a modest, advisory body requested by Indigenous Australians in the Uluru Statement from the Heart.", "raised_by": ["Federal Coalition", "No campaign"], "sources": [{"title": "Why did the Voice referendum fail? We crunched the data and found 6 reasons (The Conversation)", "url": "https://theconversation.com/why-did-the-voice-referendum-fail-we-crunched-the-data-and-found-6-reasons-228383"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31", "public_reaction": {"summary": "At the referendum on 14 October 2023, 60.06% voted No (9,452,792) and 39.94% Yes (6,286,894) on a turnout of 89.95%; no state returned a Yes majority (the ACT voted 61.29% Yes). Polling had shown Yes ahead 58–42 in Resolve in April 2023 before No led from June and reached 58–34 in the final Newspoll. The final YouGov poll found under-25s voting Yes 58–32 while over-65s voted No 67–29, and the ANU's post-referendum study found Yes support ranged from about 20% among people without Year 12 to about 60% among postgraduates. 'Walk for Yes' rallies on 16–17 September 2023 drew about 30,000 in Melbourne (police estimate) and tens of thousands in Sydney; the parliamentary inquiry into the bill received 269 submissions.", "sources": [{"title": "2023 Referendum national results (Australian Electoral Commission)", "url": "https://results.aec.gov.au/29581/Website/ReferendumNationalResults-29581.htm", "date": "2023-10"}, {"title": "Final YouGov Voice referendum poll: No increases lead to 18 points", "url": "https://yougov.com/articles/47566-final-yougov-voice-referendum-poll-no-increases-lead-to-18-points", "date": "2023-10-12"}, {"title": "Tens of thousands hit the streets in support of the referendum (ABC News)", "url": "https://www.abc.net.au/news/2023-09-17/yes-vote-voice-referendum-marches-australia/102862580", "date": "2023-09-17"}, {"title": "Voters rejected Voice due to fears of division: ANU study", "url": "https://www.anu.edu.au/news/all-news/voters-rejected-voice-due-to-fears-of-division-anu-study", "date": "2023-11-28"}]}}, {"id": "public-interest-disclosure-amendment-review-act-2023", "title": "Public Interest Disclosure Amendment (Review) Bill 2022", "status": "passed", "status_date": "2023-06-19", "status_note": "Introduced 30 Nov 2022; passed both Houses 15 Jun 2023; assented 19 Jun 2023 (Act No. 23 of 2023)", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r6958", "legislation_url": "https://www.legislation.gov.au/C2023A00023/latest/text", "summary": "Amends the Public Interest Disclosure Act 2013 as a first stage of whistleblower reform: it excludes 'personal work-related conduct' from the scheme, expands protections and civil remedies for reprisals, removes the general secrecy offence, clarifies the roles of the Ombudsman and IGIS, and provides for a five-year review. Consequential amendments align the Act with the National Anti-Corruption Commission.", "controversy": {"category": "Other", "summary": "The Human Rights Law Centre, Transparency International Australia and Griffith University's Centre for Governance and Public Policy welcomed the technical reforms in a joint submission but warned against a 'piecemeal approach', noting that of 21 reform areas in their federal roadmap the bill addressed only one completely and four partially, and called for a whistleblower protection authority. The government described the bill as priority reforms ahead of a broader second stage.", "raised_by": ["Human Rights Law Centre", "Transparency International Australia", "Griffith University Centre for Governance and Public Policy"], "sources": [{"title": "Joint Submission - Inquiry into the Public Interest Disclosure Amendment (Review) Bill 2022 (Transparency International Australia)", "url": "https://transparency.org.au/joint-submission-whistle-blower-protections/"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "national-anti-corruption-commission-act-2022", "title": "National Anti-Corruption Commission Bill 2022", "status": "passed", "status_date": "2022-12-12", "status_note": "Introduced 28 Sep 2022; passed both Houses 30 Nov 2022 with 36 government and 2 Greens amendments; assented 12 Dec 2022 (Act No. 88 of 2022); Commission commenced 1 Jul 2023", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r6917", "legislation_url": "https://www.legislation.gov.au/C2022A00088/latest/text", "summary": "Establishes the National Anti-Corruption Commission to investigate and report on serious or systemic corruption in the Commonwealth public sector, refer evidence of criminal conduct for prosecution and undertake education and prevention. It creates a Parliamentary Joint Committee and an independent Inspector to oversee the Commission. Public hearings may be held only in 'exceptional circumstances' and where in the public interest.", "controversy": {"category": "Democratic process", "summary": "Seven integrity organisations including the Centre for Public Integrity, Transparency International Australia and the Human Rights Law Centre (joint statement 22 Nov 2022) called for removal of the 'exceptional circumstances' test for public hearings, with Anthony Whealy KC calling it 'excessive, redundant and a serious retraction by Labor'. The Accountability Roundtable said 'it is difficult to see what example would meet this test' (ABC, 18 Oct 2022). Attorney-General Mark Dreyfus said the test struck 'the right balance', citing that only around 5 per cent of NSW ICAC hearings are public.", "raised_by": ["Centre for Public Integrity", "Transparency International Australia", "Human Rights Law Centre", "Accountability Roundtable"], "sources": [{"title": "Joint statement on the National Anti-Corruption Commission Bill 2022 (Transparency International Australia)", "url": "https://transparency.org.au/joint-statement-on-the-national-anti-corruption-commission-bill-2022/"}, {"title": "National anti-corruption commission's 'exceptional circumstances' test for public hearings could be misused, lawyers warn (ABC News)", "url": "https://www.abc.net.au/news/2022-10-18/lawyers-criticise-nacc-public-hearing-test/101547324"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "fair-work-legislation-amendment-secure-jobs-better-pay-act-2022", "title": "Fair Work Legislation Amendment (Secure Jobs, Better Pay) Bill 2022", "status": "repealed", "status_date": "2022-12-06", "status_note": "Abolished the Australian Building and Construction Commission and the Registered Organisations Commission. Passed both Houses 2 Dec 2022 with 68 government, 3 Greens and 3 Pocock amendments; assented 6 Dec 2022 (Act No. 79 of 2022).", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r6941", "legislation_url": "https://www.legislation.gov.au/C2022A00079/latest/text", "summary": "Abolishes the Australian Building and Construction Commission (renaming its Act the Federal Safety Commissioner Act) and repeals the Building Code, and abolishes the Registered Organisations Commission. It also amends the Fair Work Act 2009 to expand multi-employer bargaining, prohibit pay secrecy, limit fixed-term contracts, add job security and gender equity to the Act's objects, and create Pay Equity and Care and Community Sector expert panels.", "controversy": {"category": "Workers & business", "summary": "Six employer bodies - ACCI, Ai Group, the Business Council of Australia, COSBOA, the Minerals Council and the National Farmers' Federation - issued a joint statement (9 Nov 2022) saying the bill 'unjustifiably expands the scope for multi-employer bargaining', 'undermines the system of enterprise bargaining' and 'would not deliver any identifiable path to productivity improvements', and called for the bargaining provisions to be abandoned or substantially amended. The government argued the changes would get wages moving and close the gender pay gap.", "raised_by": ["Australian Chamber of Commerce and Industry", "Australian Industry Group", "Business Council of Australia", "Council of Small Business Organisations Australia", "Minerals Council of Australia", "National Farmers' Federation"], "sources": [{"title": "Leading employer organisations join in call for major rethink of Federal Government's IR Bill (Ai Group)", "url": "https://www.australianindustrygroup.com.au/news/media-centre/2022/leading-employer-organisations-join-together-in-call-for-a-major-rethink-of-federal-governments-ir-bill/"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "social-security-administration-amendment-repeal-of-cashless-debit-card-and-other-measures-act-2022", "title": "Social Security (Administration) Amendment (Repeal of Cashless Debit Card and Other Measures) Bill 2022", "status": "repealed", "status_date": "2022-09-30", "status_note": "Repealed the cashless debit card program. Passed both Houses 28 Sep 2022 with 34 government and 3 Greens amendments; assented 30 Sep 2022 (Act No. 39 of 2022); participants able to exit from 4 Oct 2022.", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r6887", "legislation_url": "https://www.legislation.gov.au/C2022A00039/latest/text", "summary": "Amends the Social Security (Administration) Act 1999 to abolish the cashless welfare arrangements known as the cashless debit card, allowing existing participants to exit the program or move to alternative income management arrangements, including on a voluntary basis. It makes consequential amendments to family assistance, social security and national emergency legislation.", "controversy": {"category": "Other", "summary": "Coalition senators recommended the bill not be passed. Liberal Senator Linda Reynolds warned abolition would mean 'more grog ... more violence ... more child neglect', and NT Senator Jacinta Nampijinpa Price said the government was ignoring vulnerable children in favour of adults 'controlled by addiction' (ABC, 28 Sep 2022). The Greens supported abolition but criticised the continuation of any income management. Social Services Minister Amanda Rishworth said the card had not worked and that the government wanted income management to become voluntary after consulting communities.", "raised_by": ["Federal Opposition (Linda Reynolds, Jacinta Nampijinpa Price)", "Australian Greens"], "sources": [{"title": "Cashless debit card to be abolished, but a new income-management system will take its place for some (ABC News)", "url": "https://www.abc.net.au/news/2022-09-28/cashless-debit-card-abolished-new-income-management/101480280"}]}, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}, {"id": "climate-change-act-2022", "title": "Climate Change Bill 2022", "status": "passed", "status_date": "2022-09-13", "status_note": "Introduced 27 Jul 2022; passed both Houses 8 Sep 2022 with non-government and Pocock amendments; assented 13 Sep 2022 (Act No. 37 of 2022)", "parliament_url": "https://www.aph.gov.au/Parliamentary_Business/Bills_Legislation/Bills_Search_Results/Result?bId=r6885", "legislation_url": "https://www.legislation.gov.au/C2022A00037/latest/text", "summary": "Legislates Australia's greenhouse gas emissions reduction targets of 43 per cent below 2005 levels by 2030 and net zero by 2050. It requires the Minister to table an annual climate change statement, requires the Climate Change Authority to advise on future targets, and provides for periodic reviews of the Act.", "controversy": null, "verified_on": "2026-09-18", "recheck_by": "2027-03-31"}], "generated_at": "2026-09-17T15:24:04+00:00"};
